        self.assertEqual(resp.status, 200, resp.body)
        status = {c["id"]: c["ledger_status"] for c in resp.body["items"]}
        self.assertEqual(status[self.pending], None)
        for cid in self.ids:
            self.assertEqual(status[cid], "booked", cid)


